with target as(select * from public.works where id=any(array[]::bigint[]) or open_library_id=any(array['OL972159W','OL972164W','OL972166W','OL972168W','OL972172W','OL972174W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['dehel','eenboekenkastopreis','goetheengeeneinde','hetgeheimvaneberwein','weerzien','eilanden']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['dehel','eenboekenkastopreis','goetheengeeneinde','hetgeheimvaneberwein','weerzien','eilanden']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL88547A','OL3192602A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['boudewijnbuch']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL1203440M','OL134301M','OL1604031M','OL3753400M','OL2988580M','OL3846753M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789025403096','9789029503426','9789029506342','9789029504379','9789029508469','9789060197523']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
